=Aşağıdaki ders notu metninden Türkçe 5 adet çoktan seçmeli soru üret.

Metin:
{{ $json.body.text }}

parameters.jsCode:
const rawInput = $input.first().json;
const webhookBody = $('Webhook Generate Quiz').first().json.body || {};

// AI Agent / Groq yanıtını al
let rawText =
  rawInput?.output ||
  rawInput?.content ||
  rawInput?.message?.content ||
  rawInput?.text ||
  rawInput?.response ||
  (typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput));

if (typeof rawText === 'object') {
  rawText = JSON.stringify(rawText);
}

// Markdown kod bloklarını temizle ve ilk { ile son } arasını al
rawText = String(rawText).replace(/```json/gi, '').replace(/```/g, '').trim();
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) {
  rawText = rawText.slice(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(rawText);
  if (typeof parsed?.content === 'string') {
    parsed = JSON.parse(parsed.content);
  }
} catch (err) {
  throw new Error(`JSON_PARSE_ERROR: Model gecerli JSON uretmedi. Ham cikti: ${rawText.slice(0, 200)}`);
}

// Sorular dizisini bul
const rawQuestions = Array.isArray(parsed)
  ? parsed
  : Array.isArray(parsed?.questions)
    ? parsed.questions
    : [];

if (rawQuestions.length < 3) {
  throw new Error(`SCHEMA_ERROR: Yetersiz soru sayisi (${rawQuestions.length}).`);
}

// Her soruyu doğrula ve normalize et
const validatedQuestions = rawQuestions.map((q, index) => {
  const questionText = String(q?.question || '').trim();
  const options = Array.isArray(q?.options)
    ? q.options.map((opt) => String(opt).trim()).filter(Boolean)
    : [];
  let correctAnswer = String(q?.correct_answer || '').trim();

  if (!questionText || options.length < 4) {
    throw new Error(`SCHEMA_ERROR: Soru ${index + 1} eksik veya 4 secenegi yok.`);
  }

  // Eğer model correct_answer olarak sadece harf döndürdüyse ilgili şıkka eşle
  if (!options.includes(correctAnswer)) {
    const matched = options.find((opt) =>
      opt.toUpperCase().startsWith(correctAnswer.toUpperCase() + ':') ||
      opt.toUpperCase().startsWith(correctAnswer.toUpperCase() + ')')
    );
    correctAnswer = matched || options[0];
  }

  return {
    id: index + 1,
    question: questionText,
    options: options.slice(0, 4),
    correct_answer: correctAnswer
  };
});

return [
  {
    json: {
      source_id: webhookBody.source_id || null,
      title: webhookBody.title || 'Ders Testi',
      questions: validatedQuestions,
      created_at: new Date().toISOString()
    }
  }
];

const validatedData = $('Validate Quiz Schema').first().json;
const mongoResult = $input.first().json;

// MongoDB _id / id buffer nesnesini temiz 24 haneli hex string'e çevir
const rawId = mongoResult.id || mongoResult._id || mongoResult.insertedId;
let quizId = null;
if (typeof rawId === 'string') {
  quizId = rawId;
} else if (rawId && rawId.buffer) {
  quizId = Object.values(rawId.buffer)
    .map((b) => Number(b).toString(16).padStart(2, '0'))
    .join('');
}

const clientQuestions = validatedData.questions.map(q => ({
  id: q.id,
  question: q.question,
  options: q.options
}));

return [
  {
    json: {
      quiz_id: quizId,
      title: validatedData.title,
      total_questions: clientQuestions.length,
      questions: clientQuestions
    }
  }
];
